# Geographic Performance Optimization
# Monitor Legislativo v4 - Large Dataset Performance System
# =========================================================

#' Performance Optimization for Geographic Data Processing
#' 
#' Advanced performance optimization utilities for handling large geographic datasets
#' with Railway deployment constraints (2GB memory limit). Includes data streaming,
#' progressive loading, and memory management specifically for Brazilian legislative data.

library(dplyr)
library(data.table)
library(sf)
library(memoise)
library(future)
library(future.apply)

# Configuration for Railway deployment
RAILWAY_MEMORY_LIMIT <- 2 * 1024^3  # 2GB in bytes
MAX_CHUNK_SIZE <- 10000              # Documents per processing chunk
MAX_BOUNDARY_FEATURES <- 1000        # Maximum boundary features to load
CACHE_SIZE_LIMIT <- 100 * 1024^2     # 100MB cache limit

#' Initialize Performance Monitoring
#' 
#' Sets up performance monitoring for geographic operations.
#' 
#' @return list with performance monitoring functions
#' @export
init_performance_monitor <- function() {
  start_time <- Sys.time()
  memory_start <- as.numeric(object.size(ls(envir = globalenv())))\n  \n  list(\n    start_time = start_time,\n    memory_start = memory_start,\n    \n    # Memory usage checker\n    check_memory = function() {\n      current_usage <- as.numeric(object.size(ls(envir = globalenv())))\n      percentage <- (current_usage / RAILWAY_MEMORY_LIMIT) * 100\n      \n      list(\n        current_mb = round(current_usage / 1024^2, 1),\n        percentage = round(percentage, 1),\n        available_mb = round((RAILWAY_MEMORY_LIMIT - current_usage) / 1024^2, 1),\n        warning = percentage > 80\n      )\n    },\n    \n    # Performance summary\n    summary = function() {\n      end_time <- Sys.time()\n      duration <- as.numeric(difftime(end_time, start_time, units = \"secs\"))\n      memory_end <- as.numeric(object.size(ls(envir = globalenv())))\n      \n      list(\n        duration_seconds = round(duration, 2),\n        memory_change_mb = round((memory_end - memory_start) / 1024^2, 2),\n        operations_per_second = if(duration > 0) round(1/duration, 2) else NA\n      )\n    }\n  )\n}\n\n#' Process Geographic Data in Chunks\n#' \n#' Processes large geographic datasets in manageable chunks to avoid memory issues.\n#' \n#' @param data_source Character path to data file or data.frame\n#' @param processing_function Function to apply to each chunk\n#' @param chunk_size Integer size of each chunk\n#' @param progress_callback Function to call with progress updates\n#' @return list with processed results\n#' @export\nprocess_geographic_chunks <- function(data_source, processing_function, \n                                     chunk_size = MAX_CHUNK_SIZE, \n                                     progress_callback = NULL) {\n  \n  cat(\"🔄 Starting chunked geographic processing...\\n\")\n  monitor <- init_performance_monitor()\n  \n  tryCatch({\n    # Determine total records\n    if (is.character(data_source) && file.exists(data_source)) {\n      # Count lines for file-based processing\n      total_records <- as.numeric(system(paste(\"wc -l\", data_source), intern = TRUE))\n      total_records <- as.numeric(gsub(\"\\\\s.*\", \"\", total_records)) - 1  # Subtract header\n    } else if (is.data.frame(data_source)) {\n      total_records <- nrow(data_source)\n      data_source <- data_source  # Use directly\n    } else {\n      stop(\"Invalid data source\")\n    }\n    \n    total_chunks <- ceiling(total_records / chunk_size)\n    cat(\"📊 Processing\", total_records, \"records in\", total_chunks, \"chunks\\n\")\n    \n    results <- list()\n    processed_count <- 0\n    \n    for (chunk_num in 1:total_chunks) {\n      # Check memory before processing chunk\n      memory_status <- monitor$check_memory()\n      if (memory_status$warning) {\n        warning(\"Memory usage high: \", memory_status$percentage, \"%. Running garbage collection.\")\n        gc()\n        \n        # Check again after GC\n        memory_status <- monitor$check_memory()\n        if (memory_status$percentage > 90) {\n          stop(\"Memory usage critical: \", memory_status$percentage, \"%. Stopping processing.\")\n        }\n      }\n      \n      # Calculate chunk boundaries\n      start_row <- (chunk_num - 1) * chunk_size + 1\n      end_row <- min(chunk_num * chunk_size, total_records)\n      \n      # Load chunk data\n      if (is.character(data_source) && file.exists(data_source)) {\n        # File-based chunked reading\n        chunk_data <- data.table::fread(\n          data_source,\n          nrows = end_row - start_row + 1,\n          skip = start_row,\n          header = chunk_num == 1\n        )\n      } else {\n        # Data frame slicing\n        chunk_data <- data_source[start_row:end_row, ]\n      }\n      \n      if (nrow(chunk_data) == 0) {\n        next\n      }\n      \n      # Process chunk\n      chunk_result <- tryCatch({\n        processing_function(chunk_data)\n      }, error = function(e) {\n        warning(\"Error processing chunk \", chunk_num, \": \", e$message)\n        NULL\n      })\n      \n      if (!is.null(chunk_result)) {\n        results[[paste0(\"chunk_\", chunk_num)]] <- chunk_result\n      }\n      \n      processed_count <- processed_count + nrow(chunk_data)\n      \n      # Progress callback\n      if (!is.null(progress_callback)) {\n        progress_callback(\n          chunk = chunk_num,\n          total_chunks = total_chunks,\n          records_processed = processed_count,\n          total_records = total_records,\n          percentage = round((processed_count / total_records) * 100, 1)\n        )\n      }\n      \n      # Clean up chunk data to free memory\n      rm(chunk_data)\n      if (chunk_num %% 5 == 0) {\n        gc()  # Garbage collection every 5 chunks\n      }\n    }\n    \n    # Combine results efficiently\n    combined_results <- combine_chunk_results(results)\n    \n    # Performance summary\n    perf_summary <- monitor$summary()\n    cat(\"✅ Chunked processing complete:\\n\")\n    cat(\"   - Duration:\", perf_summary$duration_seconds, \"seconds\\n\")\n    cat(\"   - Memory change:\", perf_summary$memory_change_mb, \"MB\\n\")\n    cat(\"   - Records processed:\", processed_count, \"\\n\")\n    \n    return(combined_results)\n    \n  }, error = function(e) {\n    cat(\"❌ Error in chunked processing:\", e$message, \"\\n\")\n    return(list(error = e$message))\n  })\n}\n\n#' Combine Chunk Results Efficiently\n#' \n#' Efficiently combines results from chunked processing.\n#' \n#' @param chunk_results list of chunk results\n#' @return combined result\ncombine_chunk_results <- function(chunk_results) {\n  if (length(chunk_results) == 0) {\n    return(data.frame())\n  }\n  \n  # Check if results are data frames\n  are_dataframes <- sapply(chunk_results, is.data.frame)\n  \n  if (all(are_dataframes)) {\n    # Fast rbind for data frames\n    return(data.table::rbindlist(chunk_results, use.names = TRUE, fill = TRUE))\n  } else if (all(sapply(chunk_results, is.list))) {\n    # Combine lists\n    return(do.call(c, chunk_results))\n  } else {\n    # Mixed types - return as list\n    return(chunk_results)\n  }\n}\n\n#' Optimize Spatial Data for Railway\n#' \n#' Optimizes spatial data specifically for Railway deployment constraints.\n#' \n#' @param spatial_data sf object or data frame with coordinates\n#' @param target_size_mb Target size in megabytes\n#' @param simplification_tolerance Tolerance for geometry simplification\n#' @return optimized spatial data\n#' @export\noptimize_spatial_for_railway <- function(spatial_data, target_size_mb = 50, \n                                         simplification_tolerance = 0.01) {\n  \n  cat(\"⚡ Optimizing spatial data for Railway deployment...\\n\")\n  \n  tryCatch({\n    if (is.null(spatial_data) || nrow(spatial_data) == 0) {\n      return(spatial_data)\n    }\n    \n    # Check current size\n    current_size_mb <- as.numeric(object.size(spatial_data)) / 1024^2\n    cat(\"📏 Current size:\", round(current_size_mb, 1), \"MB\\n\")\n    \n    if (current_size_mb <= target_size_mb) {\n      cat(\"✅ Data already within target size\\n\")\n      return(spatial_data)\n    }\n    \n    optimized_data <- spatial_data\n    \n    # Step 1: Remove unnecessary columns\n    if (ncol(optimized_data) > 10) {\n      # Keep only essential columns\n      essential_cols <- c(\"geometry\", \"id\", \"name\", \"state\", \"region\", \n                         \"state_abbr\", \"state_name\", \"region_name\")\n      available_cols <- intersect(essential_cols, names(optimized_data))\n      \n      if (length(available_cols) > 0) {\n        optimized_data <- optimized_data[, available_cols]\n        cat(\"🔧 Reduced columns from\", ncol(spatial_data), \"to\", length(available_cols), \"\\n\")\n      }\n    }\n    \n    # Step 2: Simplify geometries if sf object\n    if (inherits(optimized_data, \"sf\")) {\n      # Make geometries valid first\n      optimized_data <- sf::st_make_valid(optimized_data)\n      \n      # Simplify geometries\n      optimized_data <- sf::st_simplify(\n        optimized_data, \n        dTolerance = simplification_tolerance,\n        preserveTopology = TRUE\n      )\n      \n      # Remove empty geometries\n      empty_geoms <- sf::st_is_empty(optimized_data)\n      if (any(empty_geoms)) {\n        optimized_data <- optimized_data[!empty_geoms, ]\n        cat(\"🧹 Removed\", sum(empty_geoms), \"empty geometries\\n\")\n      }\n      \n      # Transform to efficient CRS if needed\n      if (sf::st_crs(optimized_data)$input != \"EPSG:4326\") {\n        optimized_data <- sf::st_transform(optimized_data, crs = 4326)\n      }\n    }\n    \n    # Step 3: Limit number of features if still too large\n    new_size_mb <- as.numeric(object.size(optimized_data)) / 1024^2\n    \n    if (new_size_mb > target_size_mb && nrow(optimized_data) > MAX_BOUNDARY_FEATURES) {\n      # Select most important features (by area or importance)\n      if (inherits(optimized_data, \"sf\")) {\n        # Calculate areas and keep largest features\n        optimized_data$area <- as.numeric(sf::st_area(optimized_data))\n        optimized_data <- optimized_data %>%\n          arrange(desc(area)) %>%\n          slice_head(n = MAX_BOUNDARY_FEATURES) %>%\n          select(-area)\n      } else {\n        optimized_data <- optimized_data[1:min(MAX_BOUNDARY_FEATURES, nrow(optimized_data)), ]\n      }\n      \n      cat(\"📉 Limited features to\", nrow(optimized_data), \"\\n\")\n    }\n    \n    # Final size check\n    final_size_mb <- as.numeric(object.size(optimized_data)) / 1024^2\n    reduction_pct <- round((1 - final_size_mb / current_size_mb) * 100, 1)\n    \n    cat(\"✅ Optimization complete:\\n\")\n    cat(\"   - Original size:\", round(current_size_mb, 1), \"MB\\n\")\n    cat(\"   - Optimized size:\", round(final_size_mb, 1), \"MB\\n\")\n    cat(\"   - Reduction:\", reduction_pct, \"%\\n\")\n    cat(\"   - Features:\", nrow(optimized_data), \"\\n\")\n    \n    return(optimized_data)\n    \n  }, error = function(e) {\n    warning(\"Error optimizing spatial data: \", e$message)\n    return(spatial_data)\n  })\n}\n\n#' Progressive Data Loading for Geographic Analysis\n#' \n#' Implements progressive loading of geographic data based on zoom level and viewport.\n#' \n#' @param full_dataset data.frame or path to full dataset\n#' @param zoom_level Numeric current zoom level\n#' @param bbox List with bounding box coordinates (xmin, ymin, xmax, ymax)\n#' @param max_features Integer maximum features to return\n#' @return subset of data appropriate for current view\n#' @export\nprogressive_load_geographic <- function(full_dataset, zoom_level = 4, \n                                       bbox = NULL, max_features = 1000) {\n  \n  cat(\"📱 Progressive loading for zoom level\", zoom_level, \"\\n\")\n  \n  tryCatch({\n    # Load full dataset if path provided\n    if (is.character(full_dataset) && file.exists(full_dataset)) {\n      # Use data.table for fast reading with filtering\n      data <- data.table::fread(full_dataset, nrows = max_features * 2)\n    } else if (is.data.frame(full_dataset)) {\n      data <- full_dataset\n    } else {\n      warning(\"Invalid dataset provided\")\n      return(data.frame())\n    }\n    \n    if (nrow(data) == 0) {\n      return(data.frame())\n    }\n    \n    # Filter by bounding box if provided\n    if (!is.null(bbox) && all(c(\"latitude\", \"longitude\") %in% names(data))) {\n      data <- data %>%\n        filter(\n          longitude >= bbox$xmin & longitude <= bbox$xmax &\n          latitude >= bbox$ymin & latitude <= bbox$ymax\n        )\n    }\n    \n    # Adjust data density based on zoom level\n    if (zoom_level <= 4) {\n      # Country level - show only major cities/states\n      sample_rate <- min(max_features / nrow(data), 0.1)\n    } else if (zoom_level <= 6) {\n      # Regional level - show state capitals and major cities\n      sample_rate <- min(max_features / nrow(data), 0.3)\n    } else if (zoom_level <= 8) {\n      # State level - show more detail\n      sample_rate <- min(max_features / nrow(data), 0.6)\n    } else {\n      # City level - show full detail within limits\n      sample_rate <- min(max_features / nrow(data), 1.0)\n    }\n    \n    # Sample data if needed\n    if (sample_rate < 1.0 && nrow(data) > max_features) {\n      sample_size <- max(1, round(nrow(data) * sample_rate))\n      \n      # Use stratified sampling if state/region information available\n      if (\"estado\" %in% names(data) || \"state\" %in% names(data)) {\n        group_col <- if (\"estado\" %in% names(data)) \"estado\" else \"state\"\n        data <- data %>%\n          group_by(get(group_col)) %>%\n          slice_sample(n = max(1, sample_size %/% n_distinct(get(group_col)))) %>%\n          ungroup()\n      } else {\n        # Simple random sampling\n        data <- data %>%\n          slice_sample(n = sample_size)\n      }\n    }\n    \n    cat(\"📊 Loaded\", nrow(data), \"features for zoom level\", zoom_level, \"\\n\")\n    return(data)\n    \n  }, error = function(e) {\n    warning(\"Error in progressive loading: \", e$message)\n    return(data.frame())\n  })\n}\n\n#' Memory-Efficient Spatial Join\n#' \n#' Performs spatial joins with memory optimization for large datasets.\n#' \n#' @param points_data data.frame with point data\n#' @param polygons_data sf object with polygon boundaries\n#' @param chunk_size Integer size of processing chunks\n#' @return data.frame with join results\n#' @export\nmemory_efficient_spatial_join <- function(points_data, polygons_data, \n                                          chunk_size = MAX_CHUNK_SIZE) {\n  \n  cat(\"🔗 Performing memory-efficient spatial join...\\n\")\n  \n  tryCatch({\n    if (nrow(points_data) == 0 || nrow(polygons_data) == 0) {\n      return(points_data)\n    }\n    \n    # Process in chunks if dataset is large\n    if (nrow(points_data) > chunk_size) {\n      join_function <- function(chunk_data) {\n        # Convert chunk to sf points\n        if (all(c(\"latitude\", \"longitude\") %in% names(chunk_data))) {\n          points_sf <- sf::st_as_sf(\n            chunk_data,\n            coords = c(\"longitude\", \"latitude\"),\n            crs = 4326\n          )\n        } else {\n          return(chunk_data)  # Return unchanged if no coordinates\n        }\n        \n        # Perform spatial join\n        joined <- sf::st_join(points_sf, polygons_data, join = sf::st_within)\n        \n        # Convert back to data frame\n        result <- sf::st_drop_geometry(joined)\n        \n        # Clean up\n        rm(points_sf, joined)\n        gc()\n        \n        return(result)\n      }\n      \n      # Process in chunks\n      result <- process_geographic_chunks(\n        data_source = points_data,\n        processing_function = join_function,\n        chunk_size = chunk_size\n      )\n      \n      # Combine results\n      if (is.list(result) && length(result) > 0) {\n        result <- combine_chunk_results(result)\n      }\n      \n    } else {\n      # Process all at once for smaller datasets\n      points_sf <- sf::st_as_sf(\n        points_data,\n        coords = c(\"longitude\", \"latitude\"),\n        crs = 4326\n      )\n      \n      joined <- sf::st_join(points_sf, polygons_data, join = sf::st_within)\n      result <- sf::st_drop_geometry(joined)\n    }\n    \n    cat(\"✅ Spatial join completed for\", nrow(result), \"points\\n\")\n    return(result)\n    \n  }, error = function(e) {\n    warning(\"Error in spatial join: \", e$message)\n    return(points_data)\n  })\n}\n\n#' Clean Up Geographic Objects\n#' \n#' Cleans up large geographic objects from memory.\n#' \n#' @param keep_objects Character vector of object names to keep\n#' @export\ncleanup_geographic_memory <- function(keep_objects = c()) {\n  cat(\"🧹 Cleaning up geographic objects from memory...\\n\")\n  \n  # Get current memory usage\n  before_cleanup <- as.numeric(object.size(ls(envir = globalenv()))) / 1024^2\n  \n  # Find large objects\n  all_objects <- ls(envir = globalenv())\n  large_objects <- character()\n  \n  for (obj_name in all_objects) {\n    if (!obj_name %in% keep_objects) {\n      obj <- get(obj_name, envir = globalenv())\n      obj_size <- as.numeric(object.size(obj)) / 1024^2\n      \n      # Remove objects larger than 10MB\n      if (obj_size > 10) {\n        large_objects <- c(large_objects, obj_name)\n      }\n    }\n  }\n  \n  # Remove large objects\n  if (length(large_objects) > 0) {\n    rm(list = large_objects, envir = globalenv())\n    cat(\"🗑️ Removed\", length(large_objects), \"large objects\\n\")\n  }\n  \n  # Force garbage collection\n  gc()\n  \n  # Report memory savings\n  after_cleanup <- as.numeric(object.size(ls(envir = globalenv()))) / 1024^2\n  memory_saved <- before_cleanup - after_cleanup\n  \n  cat(\"✅ Memory cleanup complete:\\n\")\n  cat(\"   - Before:\", round(before_cleanup, 1), \"MB\\n\")\n  cat(\"   - After:\", round(after_cleanup, 1), \"MB\\n\")\n  cat(\"   - Saved:\", round(memory_saved, 1), \"MB\\n\")\n}\n\n# Auto-cleanup for Railway deployment\nreg.finalizer(globalenv(), function(e) {\n  tryCatch(cleanup_geographic_memory(), error = function(err) {})\n}, onexit = TRUE)\n\ncat(\"✅ Geographic performance optimization system loaded successfully\\n\")